import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarRepositorio } from './solution.mjs';

test('salvar guarda e listar devolve o registro', () => {
  const repositorio = criarRepositorio();
  const pedido = { id: 1, produto: 'Café' };
  repositorio.salvar(pedido);
  assert.deepEqual(repositorio.listar(), [{ id: 1, produto: 'Café' }]);
});

test('listar devolve uma CÓPIA: mexer na devolvida não corrompe o banco', () => {
  const repositorio = criarRepositorio();
  repositorio.salvar({ id: 1, produto: 'Café' });
  const lista = repositorio.listar();
  lista.push({ id: 2, produto: 'Bolo' });
  assert.equal(repositorio.listar().length, 1);
});

test('buscarPorId acha o registro salvo e devolve null para id inexistente', () => {
  const repositorio = criarRepositorio();
  repositorio.salvar({ id: 7, produto: 'Café' });
  assert.deepEqual(repositorio.buscarPorId(7), { id: 7, produto: 'Café' });
  assert.equal(repositorio.buscarPorId(99), null);
});

test('salvar recusa o que não é objeto', () => {
  const repositorio = criarRepositorio();
  assert.throws(() => repositorio.salvar('café'));
  assert.throws(() => repositorio.salvar(null));
});

solutionCode:
// O repositório abstrai o acesso a dados: quem usa não sabe onde os dados moram.
export function criarRepositorio() {
  const registros = []; // aqui mora o "banco" — ninguém de fora mexe direto

  return {
    listar() {
      // Devolve uma CÓPIA: quem chamou pode mexer à vontade sem corromper o banco.
      return [...registros];
    },

    buscarPorId(id) {
      const achado = registros.find((registro) => registro.id === id);
      return achado === undefined ? null : achado;
    },

    salvar(registro) {
      if (typeof registro !== 'object' || registro === null) {
        throw new Error('só aceita objetos');
      }
      registros.push(registro);
      return registro;
    },
  };
}
